INSERT INTO public.categories(id,title,sort_order,rubric_no,is_active,deck) VALUES ('cosmo_client','Косметолог → Клиент',20,1,true,'cosmetology') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.directions(id,title,category_id) VALUES ('cosmo_client','Косметолог → Клиент','cosmo_client') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,title,description,batch_id) VALUES ('role_cosmetologist','role','cosmo_client','Косметолог','Вы — косметолог студии.','cosmo_v1'),('role_cosmo_client','role','cosmo_client','Клиентка','Вы — клиентка студии косметологии.','cosmo_v1'),('role_cosmo_client_m','role','cosmo_client','Клиент (мужчина)','Вы — клиент студии косметологии, мужчина.','cosmo_v1') ON CONFLICT (id) DO NOTHING;
DO $$
DECLARE r record; j int; lv text[] := ARRAY['Вопрос','Просьба','Требование']; n text; cid text;
BEGIN
FOR r IN SELECT * FROM (VALUES
(1,'Результат не как у блогера','Клиентка после чистки и пилинга недовольна: кожа покрасневшая, «не сияет, как у блогера», хотя косметолог предупреждал о периоде восстановления.',ARRAY['Это нормально, что кожа красная? У блогера после процедуры такого не было.','Сделайте что-нибудь, чтобы сегодня к вечеру лицо было ровным, у меня мероприятие.','Верните деньги — результата нет, а лицо красное!'],'skill_expert_argument','skill_deescalation','Спокойно объяснить, почему так происходит и сколько длится восстановление, дать понятный уход и назначить контрольный осмотр.','«Покраснение после пилинга — нормальная реакция, она проходит за 1–2 дня. Сегодня — успокаивающая маска и крем, который я вам дам. Послезавтра покажитесь мне, оценим результат вместе».'),
(2,'Хочу процедуру, несмотря на предупреждение','Клиентка настаивает на сильном пилинге сразу после отпуска на море, хотя косметолог объясняет, что сейчас это небезопасно для кожи.',ARRAY['А можно сегодня сделать пилинг? Я только с моря.','Я много раз делала, всё было нормально — давайте сделаем.','Я плачу — значит, делайте то, что я прошу!'],'skill_boundaries','skill_choice','Отказать от рискованной процедуры без нажима и предложить безопасную альтернативу на сегодня и дату для пилинга.','«Сейчас кожа после солнца, пилинг может оставить пятна — я не возьму на себя этот риск. Сегодня могу сделать увлажняющий уход, а пилинг — через 3 недели. Как вам удобнее?»'),
(3,'Скидка на курс задним числом','Клиентка купила одну процедуру, а через месяц увидела акцию на курс и требует пересчитать ей стоимость.',ARRAY['Можно мне пересчитать по акции? Я ведь тоже ходила.','Сделайте мне скидку, я у вас постоянная клиентка.','Пересчитайте, или я напишу везде, что вы обманываете!'],'skill_rules_policy','skill_choice','Опереться на правила студии, сохранить уважение к клиентке и предложить доступный бонус.','«Акция действует на курсы, купленные в её период — это правило для всех. Могу предложить купить курс сейчас по акционной цене, а прошлую процедуру зачесть как первую».'),
(4,'Советы из интернета','Клиентка приходит с подборкой видео и требует делать уход «как там», споря с рекомендациями косметолога.',ARRAY['Я видела в видео другой способ — может, сделаем так?','В интернете пишут, что ваш крем вредный. Используйте мой.','Я лучше знаю свою кожу! Делайте по моему плану!'],'skill_expert_argument','skill_concrete_brief','Не спорить с источником, а объяснить решение для конкретной кожи и договориться о понятном плане.','«Спасибо, что изучаете тему. Тот способ подходит для другого типа кожи. Для вашей я предлагаю такой план — давайте распишу шаги, и вы решите, согласны ли».'),
(5,'Опоздание на долгую процедуру','Клиентка опоздала на 30 минут на часовую процедуру и требует провести её полностью, хотя следом записан другой клиент.',ARRAY['Я немного опоздала, мы успеем всё сделать?','Сделайте полностью, я же заплатила за час.','Это ваши проблемы, что у вас другой клиент! Делайте всё!'],'skill_rules_policy','skill_choice','Честно назвать, что можно успеть, и дать выбор: сокращённая процедура сегодня или перенос.','«У нас осталось 30 минут, следом записан другой клиент. Могу сделать основную часть сейчас или перенести полную процедуру на удобный день. Что выберете?»'),
(6,'Жалоба при других клиентах','Клиентка громко в холле студии жалуется, что после процедуры у неё «испорчено лицо», привлекая внимание других клиентов.',ARRAY['Можно с кем-то поговорить? Мне не нравится, что с кожей после процедуры.','Посмотрите все, что со мной сделали! Мне нужен руководитель!','Я выложу фото везде, если вы сейчас же не решите!'],'skill_deescalation','skill_call_admin','Перевести разговор в спокойное место, выслушать, посмотреть кожу и подключить администратора или руководителя.','«Я вижу, что вы расстроены, и хочу разобраться. Давайте пройдём в кабинет, я посмотрю кожу, и вместе с администратором решим, что делать дальше».')
) AS t(no,title,descr,lines,sk1,sk2,task,ex) LOOP
  n := lpad(r.no::text,2,'0');
  INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id)
  VALUES ('ksol_'||n,'solution','cosmo_client','cosmo_client','kscn_'||n||'_1',r.title,r.task,r.ex,'[]'::jsonb,'[]'::jsonb,'К'||r.no,'cosmo_v1') ON CONFLICT (id) DO NOTHING;
  FOR j IN 1..3 LOOP
    cid := 'К'||r.no||'.'||j;
    INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id)
    VALUES (cid,'situation','cosmo_client','cosmo_client','kscn_'||n||'_'||j,r.title||' · '||lv[j],r.descr,r.lines[j],
      jsonb_build_array(jsonb_build_object('who','Клиентка','line',r.lines[j]),jsonb_build_object('who','Вы','line','…')),j,cid,r.sk1,'cosmo_v1') ON CONFLICT (id) DO NOTHING;
    INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id)
    VALUES ('kscn_'||n||'_'||j,'cosmo_client','cosmo_client',r.title,j,cid,jsonb_build_array(r.sk1,r.sk2),'ksol_'||n,'cosmo_v1') ON CONFLICT (id) DO NOTHING;
  END LOOP;
END LOOP;
END $$;